UPDATE appointment
status = #{status}, cancel_reason = #{cancelReason},
WHERE id = #{id}

mapper.select:
SELECT a.*, u.user_name AS patient_name, u.user_phone AS patient_phone,
       d.name AS doctor_name, d.title AS doctor_title, dep.name AS department_name,
       CASE a.time_slot WHEN 'morning' THEN '上午' WHEN 'afternoon' THEN '下午'
            WHEN 'evening' THEN '晚间' ELSE a.time_slot END AS time_slot_name
FROM appointment a
LEFT JOIN `user` u ON u.id = a.patient_id
LEFT JOIN hospital_doctor d ON d.id = a.doctor_id
LEFT JOIN department dep ON dep.id = a.department_id

    AND a.patient_id = #{patientId}
    AND a.doctor_id = #{doctorId}
    AND a.department_id = #{departmentId}
    AND a.appointment_date = #{appointmentDate}
    AND a.status = #{status}
    AND a.create_time BETWEEN #{startTime} AND #{endTime}

ORDER BY a.create_time DESC
LIMIT #{current}, #{size}

SELECT COUNT(*) FROM appointment a

    AND a.patient_id = #{patientId}
    AND a.doctor_id = #{doctorId}
    AND a.department_id = #{departmentId}
    AND a.appointment_date = #{appointmentDate}
    AND a.status = #{status}
    AND a.create_time BETWEEN #{startTime} AND #{endTime}

SELECT a.*, u.user_name AS patient_name, u.user_phone AS patient_phone,
       d.name AS doctor_name, d.title AS doctor_title, dep.name AS department_name,
       CASE a.time_slot WHEN 'morning' THEN '上午' WHEN 'afternoon' THEN '下午'
            WHEN 'evening' THEN '晚间' ELSE a.time_slot END AS time_slot_name
FROM appointment a
LEFT JOIN `user` u ON u.id = a.patient_id
LEFT JOIN hospital_doctor d ON d.id = a.doctor_id
LEFT JOIN department dep ON dep.id = a.department_id
WHERE a.doctor_id = #{doctorId}
AND a.appointment_date >= #{fromDate}
AND a.appointment_date <= #{toDate}
AND a.status = #{status}
ORDER BY a.appointment_date ASC, a.time_slot ASC, a.serial_number ASC
